<script setup lang="ts">
import { ref } from 'vue'
const token=ref(localStorage.getItem('merchant_token')||'');const username=ref('');const password=ref('');const info=ref<any>(null);const staff=ref<any[]>([]);const error=ref('');const emp=ref({username:'',password:'',display_name:'',role_code:'MERCHANT_STAFF'})
async function login(){error.value='';const r=await fetch('/api/v1/merchant/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:username.value,password:password.value})});const j=await r.json();if(!r.ok){error.value=j.detail||'登录失败';return};token.value=j.data.access_token;localStorage.setItem('merchant_token',token.value);await load()}
async function load(){const h={Authorization:`Bearer ${token.value}`};const r=await fetch('/api/v1/merchant/profile',{headers:h});if(r.ok)info.value=(await r.json()).data;else if(r.status===401)logout();const s=await fetch('/api/v1/merchant/employees',{headers:h});if(s.ok)staff.value=(await s.json()).data}
async function toggleEmployee(row:any){const r=await fetch(`/api/v1/merchant/employees/${row.id}/status`,{method:'PATCH',headers:{Authorization:`Bearer ${token.value}`,'Content-Type':'application/json'},body:JSON.stringify({status:row.status==='ACTIVE'?'DISABLED':'ACTIVE'})});if(r.ok)await load();else error.value='更新员工状态失败'}
async function addEmployee(){const r=await fetch('/api/v1/merchant/employees',{method:'POST',headers:{Authorization:`Bearer ${token.value}`,'Content-Type':'application/json'},body:JSON.stringify(emp.value)});if(r.ok){emp.value={username:'',password:'',display_name:'',role_code:'MERCHANT_STAFF'};await load()}else error.value='创建员工失败'}
function logout(){localStorage.removeItem('merchant_token');token.value='';info.value=null}
if(token.value)load()
</script>
<template><main v-if="!token" class="login"><h1>商家工作台</h1><el-input v-model="username" placeholder="商家员工账号"/><el-input v-model="password" type="password" placeholder="密码" @keyup.enter="login"/><el-button type="primary" @click="login">登录</el-button><p>{{error}}</p></main><el-container v-else class="layout"><el-aside width="220px"><h2>商家工作台</h2><el-menu><el-menu-item index="1">工作台</el-menu-item><el-menu-item index="2">当前商家</el-menu-item><el-menu-item index="3">员工与角色</el-menu-item></el-menu><el-button @click="logout">退出登录</el-button></el-aside><el-container><el-header>当前商家：{{info?.name||'加载中'}}</el-header><el-main><h1>工作台</h1><el-card v-if="info">商家 ID：{{info.id}}<br/>类型：{{info.type}}<br/>状态：{{info.status}}</el-card><h2>员工与角色</h2><el-form inline><el-form-item label="账号"><el-input v-model="emp.username"/></el-form-item><el-form-item label="姓名"><el-input v-model="emp.display_name"/></el-form-item><el-form-item label="初始密码"><el-input v-model="emp.password" type="password"/></el-form-item><el-form-item label="角色"><el-select v-model="emp.role_code"><el-option label="商家员工" value="MERCHANT_STAFF"/><el-option label="商家管理员" value="MERCHANT_ADMIN"/></el-select></el-form-item><el-button type="primary" @click="addEmployee">添加员工</el-button></el-form><p class="error">{{error}}</p><el-table :data="staff"><el-table-column prop="username" label="账号"/><el-table-column prop="display_name" label="姓名"/><el-table-column prop="status" label="状态"/><el-table-column label="操作"><template #default="s"><el-button size="small" @click="toggleEmployee(s.row)">切换状态</el-button></template></el-table-column></el-table><p>商品、订单及财务模块尚未实现。</p></el-main></el-container></el-container></template>
